var o=`0344-rouladen`;var t=`world-0344`;var i=`DE`;var a=`western-europe`;var r=4;var l=134;var s={en:`Rouladen`,ua:`Руладен`};var d={en:`A traditional Germany dish made with beef round, bacon, fermented cucumber, yellow onion. This home-style preparation follows its characteristic cooking method and uses measured ingredients.`,ua:`Традиційна страва кухні країни Німеччина. Основні інгредієнти: яловичий стегновий відруб, бекон, квашений огірок, жовта цибуля. Домашній варіант із характерною технологією та поетапно розподіленими продуктами.`};var u=[{en:`Prepare the filling ingredients: cook or soften any components that require it, let cool, then mix into an even filling.`,ua:`Підготуйте складники начинки: ті, що потребують теплової обробки, приготуйте, охолодіть і змішайте в однорідну начинку.`,t:[`chopping`,`mixing`],m:12,i:[[`beef-round`,750,`g`],[`bacon`,190,`g`],[`fermented-cucumber`,230,`g`],[`yellow-onion`,160,`g`],[`dijon-mustard`,60,`g`]]},{en:`Place a portion of prepared filling on each leaf or wrapper, tuck in the sides and roll tightly into neat parcels.`,ua:`Викладіть порцію готової начинки на кожен листок або обгортку, загорніть боки й скрутіть щільні акуратні рулетики.`,t:[`rolling-stuffed-food`],m:14,i:[]},{en:`Heat the pan over medium heat, shape or spoon out portions, and fry for about 13 minutes total until golden on both sides and fully cooked.`,ua:`Розігрійте сковороду на середньому вогні, сформуйте або викладіть порції ложкою й смажте загалом приблизно 13 хвилин до золотистості з обох боків і повної готовності.`,t:[`pan-frying`],m:13,i:[[`sunflower-oil`,50,`ml`]]},{en:`Add the braising liquid and seasonings, cover and cook gently for about 95 minutes until the meat is tender and safely cooked.`,ua:`Додайте рідину та приправи для тушкування, накрийте кришкою й готуйте на малому вогні приблизно 95 хвилин до м’якості та повної готовності м’яса.`,t:[`braising`],m:95,i:[[`beef-stock`,650,`ml`],[`dry-red-wine`,180,`ml`],[`carrot`,150,`g`]]}];var m={slug:o,id:t,country:`DE`,region:a,servings:4,minutes:134,title:s,text:d,steps:u};export{i as country,m as default,t as id,l as minutes,a as region,r as servings,o as slug,u as steps,d as text,s as title};